import { useState } from 'react'
import { MessageScroller, MessageScrollerItem } from 'moru-ui'
import { Button } from 'moru-ui'

export function ActivityStream() {
  const [messages, setMessages] = useState([{ id: 'message-1', text: 'Welcome to the project.' }])

  return (
    <div>
      <MessageScroller aria-label="Project activity" height={240} followOutput>
        {messages.map((message) => (
          <MessageScrollerItem key={message.id} messageId={message.id}>
            <p>{message.text}</p>
          </MessageScrollerItem>
        ))}
      </MessageScroller>
      <Button
        type="button"
        onClick={() =>
          setMessages((current) => [
            ...current,
            { id: 'message-' + (current.length + 1), text: 'Activity update ' + current.length },
          ])
        }
      >
        Add activity
      </Button>
    </div>
  )
}

